using OpenGameSave;
var root = Path.Combine(Path.GetTempPath(), "opengamesave-steam-" + Guid.NewGuid().ToString("N")); var apps = Path.Combine(root, "steamapps"); Directory.CreateDirectory(Path.Combine(apps, "common", "Demo Game")); File.WriteAllText(Path.Combine(apps, "libraryfolders.vdf"), $"\"library\" {{ \"path\" \"{root.Replace("\\", "\\\\")}\" }}"); File.WriteAllText(Path.Combine(apps, "appmanifest_123.acf"), "\"AppState\" { \"name\" \"Demo Game\" \"installdir\" \"Demo Game\" }"); var games = SteamDiscovery.Discover(new[] { root }); if (games.Count != 1 || games[0].AppId != "123" || games[0].Name != "Demo Game") throw new Exception("Steam discovery failed."); Directory.Delete(root, true); Console.WriteLine("PASS: Steam library and installed-game discovery");
